open.example:
const { Events } = kcds.core;

kcds.ui.CharacterCreator.open({ title: 'Who are you?', genders: 'both' });

Events.on('characterCreatorClosed', (appearance, reason) => {
  if (reason === 'accepted') {
    Events.toServer('saveLook', appearance);
  }
});

open.exampleCs:
CharacterCreator.Open(new { title = "Who are you?", genders = "both" });

Events.On("characterCreatorClosed", (JsValue appearance, JsValue reason) =>
{
    if (reason.AsString() == "accepted")
    {
        Events.ToServer("saveLook", appearance);
    }
});

preview.example:
const { Events } = kcds.core;

kcds.ui.CharacterCreator.open({ panel: false, genders: 'male' });
// The server sends the looks your editor offers (Appearances is the server's catalogue).
Events.on('looks:try', (look) => {
  kcds.ui.CharacterCreator.preview(look);
});

preview.exampleCs:
CharacterCreator.Open(new { panel = false, genders = "male" });
// The server sends the looks your editor offers (Appearances is the server's catalogue).
Events.On("looks:try", (JsValue look) =>
{
    CharacterCreator.Preview(look);
});
